import{_ as o,c,o as d,ag as t}from"./chunks/framework.ymCRTBvy.js";const h=JSON.parse('{"title":"7.2_算术运算符","description":"","frontmatter":{},"headers":[],"relativePath":"swift/basics/7.2_算术运算符.md","filePath":"swift/basics/7.2_算术运算符.md"}'),l={name:"swift/basics/7.2_算术运算符.md"};function a(r,e,i,n,s,u){return d(),c("div",null,e[0]||(e[0]=[t('<h1 id="_7-2-算术运算符" tabindex="-1">7.2_算术运算符 <a class="header-anchor" href="#_7-2-算术运算符" aria-label="Permalink to &quot;7.2_算术运算符&quot;">​</a></h1><p>Swift 6 提供了强大的算术运算符，让你能够轻松执行基本的数学计算。这些运算符是编程的基石，掌握它们将为你打开数据处理的大门！🚀</p><h2 id="加法运算符" tabindex="-1">加法运算符：<code>+</code> <a class="header-anchor" href="#加法运算符" aria-label="Permalink to &quot;加法运算符：`+`&quot;">​</a></h2><p>加法运算符 <code>+</code> 用于计算两个数值的和。无论你是处理整数还是浮点数，它都能完美胜任。例如，<code>10 + 5</code> 的结果是 <code>15</code>，而 <code>3.14 + 2.86</code> 则会得到 <code>6.0</code>。</p><ul><li><strong>整数相加</strong>：<code>let sumInt = 10 + 20</code>，<code>sumInt</code> 的值将是 <code>30</code>。</li><li><strong>浮点数相加</strong>：<code>let sumDouble = 5.5 + 4.5</code>，<code>sumDouble</code> 的值将是 <code>10.0</code>。</li><li><strong>混合类型</strong>：Swift 不允许直接将整数和浮点数相加，你需要进行类型转换。例如，<code>let result = 10 + Int(3.14)</code>。</li></ul><h2 id="减法运算符" tabindex="-1">减法运算符：<code>-</code> <a class="header-anchor" href="#减法运算符" aria-label="Permalink to &quot;减法运算符：`-`&quot;">​</a></h2><p>减法运算符 <code>-</code> 用于计算两个数值的差。它同样适用于整数和浮点数，让你能够轻松地从一个值中减去另一个值。</p><ul><li><strong>整数相减</strong>：<code>let differenceInt = 30 - 15</code>，<code>differenceInt</code> 的值是 <code>15</code>。</li><li><strong>浮点数相减</strong>：<code>let differenceDouble = 10.0 - 3.5</code>，<code>differenceDouble</code> 的值是 <code>6.5</code>。</li><li><strong>负数结果</strong>：<code>let negativeResult = 5 - 10</code>，结果是 <code>-5</code>。</li></ul><h2 id="乘法运算符" tabindex="-1">乘法运算符：<code>*</code> <a class="header-anchor" href="#乘法运算符" aria-label="Permalink to &quot;乘法运算符：`*`&quot;">​</a></h2><p>乘法运算符 <code>*</code> 用于计算两个数值的乘积。这个运算符在处理需要倍增或缩放的场景时非常有用。</p><ul><li><strong>整数相乘</strong>：<code>let productInt = 7 * 8</code>，<code>productInt</code> 的值是 <code>56</code>。</li><li><strong>浮点数相乘</strong>：<code>let productDouble = 2.5 * 4.0</code>，<code>productDouble</code> 的值是 <code>10.0</code>。</li><li><strong>应用场景</strong>：计算商品总价时，<code>let totalPrice = unitPrice * quantity</code>。</li></ul><h2 id="除法运算符" tabindex="-1">除法运算符：<code>/</code> <a class="header-anchor" href="#除法运算符" aria-label="Permalink to &quot;除法运算符：`/`&quot;">​</a></h2><p>除法运算符 <code>/</code> 用于计算两个数值的商。在 Swift 中，整数除法和浮点数除法有不同的行为，这一点非常重要！</p><ul><li><strong>整数除法</strong>：当两个操作数都是整数时，<code>/</code> 执行整数除法，结果会截断小数部分，只保留整数部分。例如，<code>10 / 3</code> 的结果是 <code>3</code>，而不是 <code>3.33</code>。</li><li><strong>浮点数除法</strong>：如果至少有一个操作数是浮点数，<code>/</code> 将执行浮点数除法，结果会包含小数部分。例如，<code>10.0 / 3</code> 的结果是 <code>3.3333333333333335</code>。</li><li><strong>避免除以零</strong>：尝试除以零会导致运行时错误，所以务必确保除数不为零。这是一个关键的安全实践！⚠️</li></ul><h2 id="运算符的优先级和结合性" tabindex="-1">运算符的优先级和结合性 <a class="header-anchor" href="#运算符的优先级和结合性" aria-label="Permalink to &quot;运算符的优先级和结合性&quot;">​</a></h2><p>算术运算符遵循标准的数学优先级规则。乘法和除法的优先级高于加法和减法。你可以使用括号 <code>()</code> 来明确指定运算顺序，确保你的计算结果符合预期。</p><p>例如：</p><ul><li><code>2 + 3 * 4</code> 的结果是 <code>14</code> (先乘后加)。</li><li><code>(2 + 3) * 4</code> 的结果是 <code>20</code> (先加后乘)。</li></ul><p>理解这些基本算术运算符是 Swift 编程的基石。它们让你能够处理各种数值数据，为构建复杂的应用程序奠定坚实的基础。继续探索，你会发现更多精彩！✨</p>',19)]))}const p=o(l,[["render",a]]);export{h as __pageData,p as default};
